import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps, type ReactNode } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

interface ChatToPreviewLayoutProps {
  chat?: ReactNode;
  preview?: ReactNode;
  startChatRatio?: number;
  endChatRatio?: number;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

function DefaultChat() {
  const messages = [
    { from: "user", text: "Build me a landing page" },
    { from: "ai", text: "Sure — what should it feature?" },
    { from: "user", text: "Hero, pricing, footer." },
    { from: "ai", text: "On it. Generating now..." },
  ];
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        padding: 24,
        display: "flex",
        flexDirection: "column",
        gap: 12,
        fontFamily: FONT_FAMILY,
        background: "#111",
      }}
    >
      <div
        style={{
          color: "#888",
          fontSize: 12,
          fontWeight: 600,
          letterSpacing: "0.08em",
          textTransform: "uppercase",
          marginBottom: 8,
        }}
      >
        Chat
      </div>
      {messages.map((m, i) => (
        <div
          key={i}
          style={{
            alignSelf: m.from === "user" ? "flex-end" : "flex-start",
            background: m.from === "user" ? "#0ea5e9" : "#262626",
            color: "white",
            padding: "10px 14px",
            borderRadius: 14,
            fontSize: 14,
            maxWidth: "85%",
          }}
        >
          {m.text}
        </div>
      ))}
    </div>
  );
}

function DefaultPreview() {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: "white",
        display: "flex",
        flexDirection: "column",
        fontFamily: FONT_FAMILY,
      }}
    >
      <div
        style={{
          height: 36,
          background: "#f4f4f5",
          borderBottom: "1px solid #e4e4e7",
          display: "flex",
          alignItems: "center",
          gap: 6,
          padding: "0 12px",
        }}
      >
        <div
          style={{
            width: 10,
            height: 10,
            borderRadius: 999,
            background: "#ef4444",
          }}
        />
        <div
          style={{
            width: 10,
            height: 10,
            borderRadius: 999,
            background: "#f59e0b",
          }}
        />
        <div
          style={{
            width: 10,
            height: 10,
            borderRadius: 999,
            background: "#22c55e",
          }}
        />
      </div>
      <div
        style={{
          flex: 1,
          padding: 32,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        <div
          style={{
            fontSize: 36,
            fontWeight: 700,
            letterSpacing: "-0.03em",
            color: "#0a0a0a",
          }}
        >
          Ship faster.
        </div>
        <div style={{ fontSize: 16, color: "#71717a", maxWidth: 360 }}>
          The fastest way to launch your idea. Built with Remotion.
        </div>
        <div
          style={{
            marginTop: 12,
            display: "inline-flex",
            background: "#0a0a0a",
            color: "white",
            padding: "10px 18px",
            borderRadius: 10,
            alignSelf: "flex-start",
            fontSize: 14,
            fontWeight: 600,
          }}
        >
          Get started
        </div>
      </div>
    </div>
  );
}

function ChatToPreviewLayoutBase({
  chat,
  preview,
  startChatRatio = 0.5,
  endChatRatio = 0.25,
  speed = 1,
  className,
}: ChatToPreviewLayoutProps) {
  const frame = useSceneFrame() * speed;
  const { durationInFrames } = useSceneConfig();

  // Apple's signature ease — slow start, dramatic settle. Replaces the older
  // symmetric bezier so the morph feels deliberate instead of mechanical.
  const APPLE_EASE = Easing.bezier(0.16, 1, 0.3, 1);

  const morphStart = durationInFrames * 0.1;
  const morphEnd = durationInFrames * 0.7;

  const ratio = interpolate(
    frame,
    [morphStart, morphEnd],
    [startChatRatio, endChatRatio],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: APPLE_EASE,
    },
  );

  // Right (preview) panel reveal: fade in + slide left into its growing slot.
  // Anchored to the same morph window so it feels like the chat is physically
  // dragging the preview into existence.
  const previewOpacity = interpolate(frame, [morphStart, morphEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: APPLE_EASE,
  });
  const previewTx = interpolate(frame, [morphStart, morphEnd], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: APPLE_EASE,
  });

  const chatBasis = `${ratio * 100}%`;
  const previewBasis = `${(1 - ratio) * 100}%`;
  // Layout rounds a box edge to whole pixels, so a preview pushed by the
  // shrinking chat column clicks left pixel by pixel. A negative margin holds
  // its layout where the morph ends and the push is a translate instead;
  // `cqw` is a percent of the row, the unit flex-basis resolves against.
  const push = ratio - endChatRatio;
  const previewShift =
    push === 0 ? `${previewTx}px` : `calc(${previewTx}px + ${push * 100}cqw)`;

  // Inner content min-widths. These are the lever that prevents text from
  // re-flowing inside the columns as the parent flex-basis morphs — content
  // is rendered at a fixed virtual width, then clipped by `overflow: hidden`
  // on the outer column. No reflow → no jumping characters.
  const CHAT_INNER_MIN = 520;
  const PREVIEW_INNER_MIN = 720;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        padding: 32,
        display: "flex",
        gap: 16,
        containerType: "inline-size",
      }}
    >
      <div
        style={{
          flexBasis: chatBasis,
          flexGrow: 0,
          flexShrink: 0,
          position: "relative",
          overflow: "hidden",
          borderRadius: 16,
          border: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            minWidth: CHAT_INNER_MIN,
          }}
        >
          {chat ?? <DefaultChat />}
        </div>
      </div>
      <div
        style={{
          flexBasis: previewBasis,
          flexGrow: 0,
          flexShrink: 0,
          position: "relative",
          overflow: "hidden",
          borderRadius: 16,
          border: "1px solid rgba(255,255,255,0.08)",
          marginLeft: push === 0 ? undefined : `${-push * 100}%`,
          opacity: previewOpacity,
          translate: previewShift,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            minWidth: PREVIEW_INNER_MIN,
          }}
        >
          {preview ?? <DefaultPreview />}
        </div>
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  startChatRatio: {
    type: "number",
    min: 0.1,
    max: 0.9,
    step: 0.05,
    default: 0.5,
    description: "Start chat ratio",
    hiddenFromList: false,
  },
  endChatRatio: {
    type: "number",
    min: 0.05,
    max: 0.9,
    step: 0.05,
    default: 0.25,
    description: "End chat ratio",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["startChatRatio","endChatRatio","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  startChatRatio: 0.5,
  endChatRatio: 0.25,
  speed: 1,
};

type ChatToPreviewLayoutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ChatToPreviewLayoutBase>;

const ChatToPreviewLayoutInner = forwardRef<
  HTMLDivElement,
  ChatToPreviewLayoutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ChatToPreviewLayout>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ChatToPreviewLayoutBase
          {...(componentProps as unknown as ComponentProps<typeof ChatToPreviewLayoutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ChatToPreviewLayout = Interactive.withSchema({
  Component: ChatToPreviewLayoutInner,
  componentName: "<ChatToPreviewLayout>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
